839	// ghRepoExists checks whether <owner>/<name> exists on GitHub.
840	func ghRepoExists(ctx context.Context, runner bootstrapRunner, owner, name string) (bool, error) {
841		_, err := runner.Run(ctx, "gh", "repo", "view", owner+"/"+name, "--json", "name")
842		if err == nil {
843			return true, nil
844		}
845		var exitErr *exec.ExitError
846		if errors.As(err, &exitErr) {
847			msg := string(exitErr.Stderr)
848			if strings.Contains(msg, "Could not resolve") || strings.Contains(msg, "not found") || strings.Contains(msg, "Not Found") {
849				return false, nil
850			}
851		}
852		return false, fmt.Errorf("gh repo view: %w", err)
853	}
