855	// ghRepoCreate creates a GitHub repo from the local source directory, adds
856	// origin as its remote, and pushes if there's anything to push.
857	func ghRepoCreate(ctx context.Context, runner bootstrapRunner, dir, fullName, visibility string, hasCommits bool) error {
858		// Create the remote repo and add origin, but don't push yet. We push
859		// separately below with --no-verify so the pre-push hook doesn't run
860		// on this first push: the entire/checkpoints/v1 branch has nothing to
861		// checkpoint (no sessions yet), and if it's pushed alongside the
862		// default branch GitHub can pick it as the default.
863		//
864		// Capture `gh repo create`'s stdout instead of streaming it — its own
865		// "✓ Created repository..." / "✓ Added remote..." lines would
866		// duplicate our own summary in runGitHubBootstrapFinalize.
867		args := []string{
868			"repo", "create", fullName,
869			"--" + visibility,
870			"--source=.",
871			"--remote=origin",
872		}
873		if _, err := runner.RunInDir(ctx, dir, "gh", args...); err != nil {
874			return fmt.Errorf("gh repo create: %w", ghRunnerErr(err))
875		}
876		if hasCommits {
877			// -q silences "Enumerating objects..." etc. --no-verify bypasses
878			// the pre-push hook so entire/checkpoints/v1 isn't pushed
879			// alongside the default branch.
880			if _, err := runner.RunInDir(ctx, dir, "git", "push", "-q", "--no-verify", "-u", "origin", "HEAD"); err != nil {
881				return fmt.Errorf("git push: %w", ghRunnerErr(err))
882			}
883		}
884		return nil
885	}
