2380	// runExplainCommit looks up the checkpoint associated with a commit.
2381	// Extracts the Entire-Checkpoint trailer and delegates to checkpoint detail view.
2382	// If no trailer found, shows a message indicating no associated checkpoint.
2383	func runExplainCommit(ctx context.Context, w, errW io.Writer, commitRef string, noPager, verbose, full, rawTranscript, generate, force, searchAll bool) error {
2384		repo, err := openRepository(ctx)
2385		if err != nil {
2386			return fmt.Errorf("not a git repository: %w", err)
2387		}
2388	
2389		// Resolve the commit reference, erroring on hex-prefix ambiguity
2390		// instead of silently picking the first matching commit.
2391		hash, ambiguousMatches, err := resolveCommitUnambiguous(repo, commitRef)
2392		if err != nil {
2393			if errors.Is(err, errAmbiguousCommitPrefix) {
2394				renderAmbiguousPrefixFailure(errW, commitRef, "commits", buildAmbiguousCommitMatches(repo, ambiguousMatches))
2395				return NewSilentError(err)
2396			}
2397			return renderExplainFailure(errW, "Commit not found", []explainRow{
2398				{Label: "ref", Value: commitRef},
2399			}, fmt.Errorf("commit not found: %s", commitRef))
2400		}
2401	
2402		commit, err := repo.CommitObject(hash)
2403		if err != nil {
2404			return fmt.Errorf("failed to get commit: %w", err)
2405		}
2406	
2407		// Extract Entire-Checkpoint trailer
2408		checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
2409		if !hasCheckpoint {
2410			// Side-effect modes must error so scripts can distinguish "done"
2411			// from "didn't happen"; read-only modes print a friendly message.
2412			if generate || rawTranscript {
2413				return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(repo, hash))
2414			}
2415			printNoTrailerMessage(w, repo, hash)
2416			return nil
2417		}
2418	
2419		// Delegate to checkpoint detail view, forwarding the full flag set so
2420		// --generate / --raw-transcript / --force work via --commit as well.
2421		return runExplainCheckpoint(ctx, w, errW, checkpointID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll)
2422	}
