103	// runStop is the main logic for the stop command.
104	func runStop(ctx context.Context, cmd *cobra.Command, sessionID string, all, force bool) error {
105		// --session path: stop a specific session by explicit ID (no worktree scoping).
106		if sessionID != "" {
107			return runStopSession(ctx, cmd, sessionID, force)
108		}
109	
110		// List all session states
111		states, err := strategy.ListSessionStates(ctx)
112		if err != nil {
113			return fmt.Errorf("failed to list sessions: %w", err)
114		}
115	
116		activeSessions := filterActiveSessions(states)
117	
118		// --all path: stop all active sessions across all worktrees.
119		if all {
120			return runStopAll(ctx, cmd, activeSessions, force)
121		}
122	
123		// No-flags path: show all active sessions across all worktrees.
124		// This aligns with `entire status` which displays sessions globally.
125		// Users see worktree labels in the multi-select to make informed choices.
126		if len(activeSessions) == 0 {
127			fmt.Fprintln(cmd.OutOrStdout(), "No active sessions.")
128			return nil
129		}
130	
131		// One active session: confirm + stop.
132		if len(activeSessions) == 1 {
133			return runStopSession(ctx, cmd, activeSessions[0].SessionID, force)
134		}
135	
136		// Multiple active sessions: show TUI multi-select.
137		return runStopMultiSelect(ctx, cmd, activeSessions, force)
138	}
