276		stats = append(stats, "started "+timeAgo(s.StartedAt))
277		if s.LastInteractionTime != nil && s.LastInteractionTime.Sub(s.StartedAt) > time.Minute {
278			stats = append(stats, activeTimeDisplay(s.LastInteractionTime))
