111	// FindMostRecentSession returns the session ID of the most recently interacted session
112	// (by LastInteractionTime) in the current worktree. Returns empty string if no sessions exist.
113	// Scoping to the current worktree prevents cross-worktree pollution in log routing.
114	// Falls back to unfiltered search if the worktree path can't be determined.
115	func FindMostRecentSession(ctx context.Context) string {
116		states, err := ListSessionStates(ctx)
117		if err != nil || len(states) == 0 {
118			return ""
119		}
120	
121		// Scope to current worktree to prevent cross-worktree pollution.
122		worktreePath, wpErr := paths.WorktreeRoot(ctx)
123		if wpErr == nil && worktreePath != "" {
124			var filtered []*SessionState
125			for _, s := range states {
126				if s.WorktreePath == worktreePath {
127					filtered = append(filtered, s)
128				}
129			}
130			if len(filtered) > 0 {
131				states = filtered
132			}
133			// If no sessions match the worktree, fall back to all sessions
134		}
135	
136		var best *SessionState
137		for _, s := range states {
138			if s.LastInteractionTime == nil {
139				continue
140			}
141			if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
142				best = s
143			}
144		}
145		if best != nil {
146			return best.SessionID
147		}
148	
149		// Fallback: return most recently started session
150		for _, s := range states {
151			if best == nil || s.StartedAt.After(best.StartedAt) {
152				best = s
153			}
154		}
155		if best != nil {
156			return best.SessionID
157		}
158		return ""
159	}
